{
  "summary": "Add immutable per-type quantity totals to ActivitySummary and snapshot summaries of retained ActivityHistory events while preserving constructor compatibility.",
  "ui_goal": "No change needed.",
  "backend_goal": "Extend ActivitySummary with immutable quantitiesByType totals for every ActivityEvent.Type, treating null quantities as zero and preserving the existing three-argument constructor; add ActivityHistory.summary() over currently retained events with snapshot semantics.",
  "tests_goal": "Add regression coverage for quantity aggregation, enum completeness, immutability, constructor compatibility, and retained-event snapshot summaries.",
  "worker_files": {
    "ui": [],
    "backend": [
      "src/main/java/dev/atmcompanion/activity/ActivitySummary.java",
      "src/main/java/dev/atmcompanion/activity/ActivityHistory.java"
    ],
    "tests": [
      "src/test/java/dev/atmcompanion/activity/ActivitySummaryTest.java",
      "src/test/java/dev/atmcompanion/activity/ActivityHistoryTest.java"
    ]
  },
  "interface_contracts": [
    {
      "name": "activity-summary-quantity-totals",
      "owner": "backend",
      "consumer_roles": ["tests"],
      "contract": "ActivitySummary exposes quantitiesByType() returning an immutable Map<ActivityEvent.Type, Long> containing every enum value. Each value is the sum of that type's event quantities, with null quantities contributing zero and absent types mapped to 0L. Preserve the existing three-argument constructor's exact parameter types and order and existing summary behavior; initialize its new quantity totals to zero when quantities are unavailable."
    },
    {
      "name": "retained-history-summary",
      "owner": "backend",
      "consumer_roles": ["tests"],
      "contract": "ActivityHistory.summary() takes no arguments and returns an ActivitySummary computed from currently retained events using existing summary semantics plus per-type quantity totals. Empty history has zero quantity totals for every type. Returned summaries retain their values after subsequent appends, including appends that evict retained events."
    }
  ],
  "provider_changes": [],
  "acceptance": [
    "Quantity totals correctly aggregate retained events by type, include all enum values, and treat null quantities as zero.",
    "The quantity map is immutable and cannot change through mutable backing state.",
    "The existing three-argument ActivitySummary constructor remains compatible and existing summary behavior is preserved.",
    "ActivityHistory.summary() summarizes only currently retained events and remains unchanged after subsequent appends or evictions.",
    "Regression coverage exercises the new behavior and compatibility."
  ],
  "worker_acceptance": {
    "ui": [],
    "backend": [
      "ActivitySummary exposes immutable, complete per-type quantity totals with null-as-zero aggregation.",
      "The existing three-argument constructor retains its signature and existing behavior, initializing unavailable quantity totals to zero.",
      "ActivityHistory.summary() computes a detached summary of current retained events, including empty history."
    ],
    "tests": [
      "ActivitySummaryTest covers multiple quantities of the same type, distinct types, null quantities, absent types, empty input, and attempted map mutation.",
      "ActivitySummaryTest covers the existing three-argument constructor and protects existing summary behavior.",
      "ActivityHistoryTest covers current retained events, empty history, exclusion of evicted events, and unchanged prior summaries after appends and eviction."
    ]
  }
}

